/* ⚠ Every name here is searched NUL-DELIMITED (\0name\0).
 * A name unique among PARSED names need not be unique in BYTES:
 * "icon_status_btl_BM_NOMIP" is a name only in lobby_2, but the same
 * bytes end a texture path in `result`. Searching bare would report the
 * wrong screen. The generator asserts the delimited form. */
#define GUI_NCORROB 6

typedef struct {
    const char *layout;      /* menu.arc resource name */
    const char *anchor;      /* name unique to this layout, else NULL */
    const char *discrim;     /* fallback: present here, absent in the
                              * most similar layout (see `versus`) */
    const char *versus;
    int         interactive; /* models SELECT/DECIDE */
    int         name_count;
    /* Other names from the SAME layout. One string matching proves
     * nothing -- a stale freed buffer matches too. Require several.
     * Only names appearing in <= 5 layouts qualify, so these are
     * evidence of WHICH layout is loaded, not just that one is.
     * `ncorrob` may be < GUI_NCORROB: a layout short of distinctive
     * names gets fewer rather than being padded with boilerplate. */
    int         ncorrob;
    const char *corrob[GUI_NCORROB];
} gui_layout_probe;

